#include <iostream>
#include <vector>
#include <string>

using namespace std;

int calculateAverage(const vector<int>& scores) {
    int total = 0;

    for (int score : scores)  {
        total += score;
    }

    return scores.empty() ? 0 : total / scores.size();}

int getScoreByIndex(const vector<int>& scores, int index) {

    if((unsigned int)index >= scores.size()) { // Check for valid index and non negative
        return -1;
    }
    else {
        return scores[index];
    }
}

void printUserReport(string* username, const vector<int>& scores) {

    if (!username)  // If the pointer is null
        return;

    cout << "User: " << *username << endl;

    int avg = calculateAverage(scores);

cout << "Average Score: " << (avg == -1 ? 0 : avg) << endl;}

int main() {

    cout << "=== AutoDev Error Testing System ===" << endl;

    vector<int> emptyScores;

    string user1 = "Alice";

    printUserReport(&user1, emptyScores);

    vector<int> validScores = {85, 90, 95};

    int badScore = getScoreByIndex(validScores, 10);

    cout << "Retrieved Score: " << (badScore == -1 ? 0 : badScore) << endl;

    string* nullUser = nullptr;

    printUserReport(nullUser, validScores);

    return 0;
}

